// Compares the API types committed in lib/api/schema.d.ts with the ones generated from the API that is deployed.
//
// The question is not "are they identical" but "did anything the app already uses break": the API keeps
// growing (new routes, new schemas, new fields) and every other open pull request would turn red each time.
// So a route or schema the committed file knows must still be there, and may only have been added to.

/**
 * Splits a file generated by openapi-typescript into its route blocks and schema blocks, by indentation.
 * @param {string} ts
 * @returns {{ paths: Map<string, string[]>, schemas: Map<string, string[]> }}
 */
export function parseBlocks(ts) {
  const paths = new Map();
  const schemas = new Map();
  const lines = ts.split("\n");

  let section = "";
  let inSchemas = false;
  let current = null; // { map, key, end }

  for (const line of lines) {
    if (current) {
      if (line === current.end) {
        current.lines.push(line);
        current.map.set(current.key, current.lines);
        current = null;
      } else {
        current.lines.push(line);
      }
      continue;
    }

    if (line.startsWith("export interface paths {")) section = "paths";
    else if (line.startsWith("export type webhooks")) section = "";
    else if (line.startsWith("export interface components {")) section = "components";

    if (section === "components") {
      if (line === "    schemas: {") inSchemas = true;
      else if (inSchemas && line === "    };") inSchemas = false;
    }

    if (section === "paths") {
      const m = /^    "([^"]+)": \{$/.exec(line);
      if (m) current = { map: paths, key: m[1], end: "    };", lines: [line] };
    } else if (section === "components" && inSchemas) {
      const m = /^        ("?[A-Za-z0-9_$.-]+"?): (.*)$/.exec(line);
      if (m && !line.startsWith("         ")) {
        if (m[2].endsWith("{")) current = { map: schemas, key: m[1], end: "        };", lines: [line] };
        else schemas.set(m[1], [line]);
      }
    }
  }
  return { paths, schemas };
}

/** Do all lines of `small` appear in `big`, in the same order? A block that only gained lines passes. */
export function isSubsequence(small, big) {
  let i = 0;
  for (const line of big) {
    if (i < small.length && line === small[i]) i++;
  }
  return i === small.length;
}

/**
 * @param {string} committed  lib/api/schema.d.ts as committed
 * @param {string} current    the same file generated from the deployed API
 * @returns {{ breaking: { kind: string, name: string, reason: string }[], additive: { kind: string, name: string }[], added: { paths: string[], schemas: string[] } }}
 */
export function compareTypes(committed, current) {
  const known = parseBlocks(committed);
  const now = parseBlocks(current);
  const breaking = [];
  const additive = [];

  for (const [kind, label] of [["paths", "route"], ["schemas", "schema"]]) {
    for (const [name, lines] of known[kind]) {
      const next = now[kind].get(name);
      if (!next) {
        breaking.push({ kind: label, name, reason: "removed" });
      } else if (next.join("\n") !== lines.join("\n")) {
        if (isSubsequence(lines, next)) additive.push({ kind: label, name });
        else breaking.push({ kind: label, name, reason: "changed" });
      }
    }
  }

  const added = {
    paths: [...now.paths.keys()].filter((p) => !known.paths.has(p)),
    schemas: [...now.schemas.keys()].filter((s) => !known.schemas.has(s)),
  };
  return { breaking, additive, added };
}
